import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    y = [n + 1] + [0] * n + [0]
    for i in range(1, len(data), 2):
        y[data[i]] = data[i + 1]

    # A path lists all isolated balls in its resulting configuration.
    # Its edges describe the open rectangles between consecutive balls.
    dp = [0] * (n + 2)
    dp[0] = 1
    for a in range(n + 1):
        if not dp[a]:
            continue
        upper = y[a]
        for b in range(a + 1, n + 2):
            lower = y[b]
            if lower >= upper:
                continue

            # An isolated point is both a prefix minimum and a suffix maximum
            # among the points in this open rectangle.
            values = []
            prefix_minima = set()
            minimum = n + 1
            for k in range(a + 1, b):
                v = y[k]
                if lower < v < upper:
                    values.append(v)
                    if v < minimum:
                        minimum = v
                        prefix_minima.add(v)

            maximum = 0
            good = True
            for v in reversed(values):
                if v > maximum:
                    if v in prefix_minima:
                        good = False
                        break
                    maximum = v

            if good:
                dp[b] = (dp[b] + dp[a]) % MOD

    print(dp[-1])


if __name__ == '__main__':
    main()

