import sys
from collections import deque

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    indegree = [0] * n
    for v in a:
        indegree[v] += 1

    queue = deque(i for i in range(n) if indegree[i] == 0)
    # dp[u][j] counts assignments below u when its value is j+1.
    # None represents an array of ones.
    dp = [None] * n
    while queue:
        u = queue.popleft()
        v = a[u]
        child = dp[u]
        dp[u] = None
        parent = dp[v]
        if child is None:
            if parent is None:
                dp[v] = list(range(1, m + 1))
            else:
                for j in range(m):
                    parent[j] = parent[j] * (j + 1) % MOD
        else:
            total = 0
            if parent is None:
                for j in range(m):
                    total = (total + child[j]) % MOD
                    child[j] = total
                dp[v] = child
            else:
                for j in range(m):
                    total = (total + child[j]) % MOD
                    parent[j] = parent[j] * total % MOD
        indegree[v] -= 1
        if indegree[v] == 0:
            queue.append(v)

    answer = 1
    for i in range(n):
        if indegree[i] == 0:
            continue
        # All vertices on a directed cycle must have equal values.
        cur = i
        product = None
        while indegree[cur]:
            indegree[cur] = 0
            row = dp[cur]
            if row is not None:
                if product is None:
                    product = row
                else:
                    for j in range(m):
                        product[j] = product[j] * row[j] % MOD
            cur = a[cur]
        ways = m if product is None else sum(product) % MOD
        answer = answer * ways % MOD
    print(answer)


if __name__ == '__main__':
    main()

