import sys

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, x in enumerate(data[1:]):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = e
            p += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (n - 1)
            factors[x][i] = 1

    answer = 1
    for p, exponents in factors.items():
        limit = max(sum(exponents), n * max(exponents))
        powers = [1] * (limit + 1)
        for j in range(limit):
            powers[j + 1] = powers[j] * p % MOD

        # Heights are normalized so that the minimum prefix height is zero.
        dp = [1]
        for i, e in enumerate(exponents, 1):
            if e == 0:
                dp = [v * powers[h] % MOD for h, v in enumerate(dp)]
                continue
            nd = [0] * (len(dp) + e)
            for h, v in enumerate(dp):
                if not v:
                    continue
                u = h + e
                nd[u] = (nd[u] + v * powers[u]) % MOD
                if h >= e:
                    u = h - e
                    nd[u] = (nd[u] + v * powers[u]) % MOD
                else:
                    # A new minimum shifts all i previous heights upwards.
                    nd[0] = (nd[0] + v * powers[i * (e - h)]) % MOD
            dp = nd
        answer = answer * (sum(dp) % MOD) % MOD
    print(answer)

if __name__ == '__main__':
    solve()

