import sys
from functools import lru_cache


def main():
    A, B, mod = map(int, sys.stdin.buffer.read().split())
    # Complementing every value swaps LIS and LDS.
    if A < B:
        A, B = B, A

    @lru_cache(None)
    def count_tableaux(shape):
        if not shape:
            return 1
        total = 0
        length = len(shape)
        for i, x in enumerate(shape):
            if i + 1 < length and x == shape[i + 1]:
                continue
            # The cell immediately below-left must precede a cell
            # in the final column.
            if x == A - 1 and i > 0 and shape[i - 1] == A:
                continue
            if x == 1:
                smaller = shape[:i] + shape[i + 1:]
            else:
                smaller = shape[:i] + (x - 1,) + shape[i + 1:]
            total += count_tableaux(smaller)
        return total % mod

    shape = (A,) * (B - 1) + (A - 1,)
    eligible = count_tableaux(shape)

    # The recording tableau is unrestricted; use the hook-length formula.
    factorial = 1
    for k in range(1, A * B):
        factorial = factorial * k % mod
    hook_product = 1
    for row in range(B):
        for col in range(shape[row]):
            below = B - 1 - row - (col == A - 1)
            hook = shape[row] - col + below
            hook_product = hook_product * hook % mod
    recording = factorial * pow(hook_product, mod - 2, mod) % mod
    print(eligible * recording % mod)


if __name__ == '__main__':
    main()

