from math import gcd


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    budget = next(it)
    processes = []
    upper = 10**9
    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        upper = min(upper, max(a, b) * (budget // min(p, q)))
        # Make the first machine at least as cost-efficient as the second.
        if a * q < b * p:
            a, p, b, q = b, q, a, p
        # Any a/gcd(a,b) second machines can be replaced by first machines.
        options = [(j * b, j * q) for j in range(a // gcd(a, b))]
        processes.append((a, p, options))

    low, high = 0, upper + 1
    while high - low > 1:
        target = (low + high) // 2
        total = 0
        for a, p, options in processes:
            best = ((target + a - 1) // a) * p
            for capacity, cost in options:
                remaining = target - capacity
                if remaining > 0:
                    cost += ((remaining + a - 1) // a) * p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                break
        if total <= budget:
            low = target
        else:
            high = target
    print(low)


