class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 1000000007
        m = min(n, x)
        dp = [0] * (m + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            for k in range(min(i, m), 0, -1):
                dp[k] = (dp[k - 1] + k * dp[k]) % mod
            dp[0] = 0
        answer = 0
        weight = 1
        for k in range(1, m + 1):
            weight = weight * (x - k + 1) * y % mod
            answer = (answer + dp[k] * weight) % mod
        return answer

