class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)

        steps = [0] * (length + 1)
        for value in range(2, length + 1):
            steps[value] = 1 + steps[value.bit_count()]

        # dp[t] counts prefixes already smaller than s, with t set bits.
        dp = [0] * (length + 1)
        ones = 0
        for i, bit in enumerate(s, 1):
            for j in range(i, 0, -1):
                dp[j] = (dp[j] + dp[j - 1]) % mod
            if bit == '1':
                # Depart from the equal prefix by choosing zero here.
                dp[ones] = (dp[ones] + 1) % mod
                ones += 1

        return sum(dp[t] for t in range(1, length + 1)
                   if steps[t] < k) % mod

