class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        w = m + 2
        size = (n + 2) * w
        a = [-1] * size
        for r, row in enumerate(grid, 1):
            a[r*w+1:r*w+m+1] = row
        expected = (2, 2, 0)
        ans = 0
        for dr, dc in ((1, 1), (1, -1), (-1, -1), (-1, 1)):
            tr, tc = dc, -dr
            step = tr*w + tc
            suffix = [0] * size
            rows = range(n, 0, -1) if tr == 1 else range(1, n+1)
            for r in rows:
                base = r*w
                for c in range(1, m+1):
                    i = base+c
                    suffix[i] = 1 + suffix[i+step] if a[i+step] == expected[a[i]] else 1
            prefix = [0] * size
            rows = range(1, n+1) if dr == 1 else range(n, 0, -1)
            step = dr*w+dc
            for r in rows:
                base = r*w
                for c in range(1, m+1):
                    i = base+c
                    v = a[i]
                    if v == 1:
                        length = 1
                    elif prefix[i-step] and expected[a[i-step]] == v:
                        length = prefix[i-step]+1
                    else:
                        continue
                    prefix[i] = length
                    total = length+suffix[i]-1
                    if total > ans:
                        ans = total
        return ans

