class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        grouped = [[] for _ in range(n)]
        for i, (l, r) in enumerate(queries):
            grouped[l].append((r, i))
        answers = [0] * len(queries)
        scores = [0] * n
        best = [0] * n
        for l in range(n - 1, -1, -1):
            score = nums[l]
            running = score
            scores[l] = score
            best[l] = score
            for r in range(l + 1, n):
                score ^= scores[r]
                scores[r] = score
                if best[r] > running:
                    running = best[r]
                if score > running:
                    running = score
                best[r] = running
            for r, i in grouped[l]:
                answers[i] = best[r]
        return answers

