class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = [x for x in p.split('*') if x]
        if not parts:
            return 0
        if len(parts) == 1:
            return len(parts[0]) if parts[0] in s else -1
        n = len(s)
        if sum(map(len, parts)) > n:
            return -1

        def occurrences(t):
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, c in enumerate(s):
                while j and c != t[j]:
                    j = pi[j - 1]
                if c == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        positions = [occurrences(t) for t in parts]
        if any(not a for a in positions):
            return -1
        lengths = list(map(len, parts))
        k = len(parts)
        pointers = [0] * k
        best = n + 1
        for start in positions[0]:
            end = start + lengths[0]
            for h in range(1, k):
                a = positions[h]
                j = pointers[h]
                while j < len(a) and a[j] < end:
                    j += 1
                pointers[h] = j
                if j == len(a):
                    return best if best <= n else -1
                end = a[j] + lengths[h]
            best = min(best, end - start)
        return best if best <= n else -1

