import heapq


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, W = data[:2]
    groups = [[] for _ in range(W + 1)]
    for i in range(2, len(data), 2):
        w, v = data[i], data[i + 1]
        if v > 1:
            groups[w].append(1 - v)

    dp = [0] * (W + 1)
    for w, heap in enumerate(groups):
        if not heap:
            continue
        heapq.heapify(heap)
        values = []
        for _ in range(W // w):
            x = heap[0]
            if x >= 0:
                break
            values.append(-x)
            heapq.heapreplace(heap, x + 2)

        if w > W // 8 or len(values) < 8:
            for value in values:
                for capacity in range(W, w - 1, -1):
                    candidate = dp[capacity - w] + value
                    if candidate > dp[capacity]:
                        dp[capacity] = candidate
        else:
            prefix = [0]
            for value in values:
                prefix.append(prefix[-1] + value)
            limit = len(values)
            new_dp = dp.copy()
            for residue in range(w):
                old = dp[residue::w]
                length = len(old)

                def compute(left, right, opt_left, opt_right):
                    if left > right:
                        return
                    mid = (left + right) // 2
                    start = max(opt_left, mid - limit)
                    end = min(mid, opt_right)
                    best = -1
                    optimum = start
                    for t in range(start, end + 1):
                        candidate = old[t] + prefix[mid - t]
                        if candidate > best:
                            best = candidate
                            optimum = t
                    new_dp[residue + mid * w] = best
                    compute(left, mid - 1, opt_left, optimum)
                    compute(mid + 1, right, optimum, opt_right)

                compute(0, length - 1, 0, length - 1)
            dp = new_dp
    print(dp[W])


