def solve():
    k = int(sys.stdin.buffer.readline())
    s = sys.stdin.buffer.readline().strip()
    t = sys.stdin.buffer.readline().strip()
    n, m = len(s), len(t)
    if abs(n - m) > k:
        print('No')
        return

    def extend(i, j):
        limit = min(n - i, m - j)
        if limit <= 0 or s[i] != t[j]:
            return i
        lo = 1
        step = 64
        while (lo + step <= limit and
               s[i + lo:i + lo + step] == t[j + lo:j + lo + step]):
            lo += step
            step *= 2
        hi = min(limit, lo + step)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if s[i + lo:i + mid] == t[j + lo:j + mid]:
                lo = mid
            else:
                hi = mid - 1
        return i + lo

    x = extend(0, 0)
    prev = {0: x}
    target = n - m
    if target == 0 and x == n:
        print('Yes')
        return

    for e in range(1, k + 1):
        cur = {}
        for d in range(-e, e + 1):
            best = -1
            x = prev.get(d, -1)
            if x >= 0 and x < n and x - d < m:
                best = x + 1
            x = prev.get(d - 1, -1)
            if x >= 0 and x < n:
                best = max(best, x + 1)
            x = prev.get(d + 1, -1)
            if x >= 0 and x - (d + 1) < m:
                best = max(best, x)
            if best >= 0:
                cur[d] = extend(best, best - d)
        if cur.get(target, -1) == n:
            print('Yes')
            return
        prev = cur
    print('No')


