from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Each subtree occupies one interval in the postorder string.
        starts = [0] * n
        ends = [0] * n
        order = []
        stack = [0]
        while stack:
            x = stack.pop()
            if x >= 0:
                starts[x] = len(order)
                stack.append(~x)
                stack.extend(reversed(children[x]))
            else:
                x = ~x
                ends[x] = len(order)
                order.append(s[x])

        # Manacher's algorithm, with separators for both palindrome parities.
        t = '^#' + '#'.join(order) + '#$'
        radius = [0] * len(t)
        center = right = 0
        for i in range(1, len(t) - 1):
            if i < right:
                radius[i] = min(right - i, radius[2 * center - i])
            r = radius[i]
            while t[i - r - 1] == t[i + r + 1]:
                r += 1
            radius[i] = r
            if i + r > right:
                center, right = i, i + r

        return [
            radius[starts[i] + ends[i] + 2] >= ends[i] - starts[i] + 1
            for i in range(n)
        ]

