class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        minima = [float('inf')] * k
        minima[0] = 0
        prefix = 0
        best = -float('inf')
        residue = 0
        for value in nums:
            prefix += value
            residue += 1
            if residue == k:
                residue = 0
            previous = minima[residue]
            candidate = prefix - previous
            if candidate > best:
                best = candidate
            if prefix < previous:
                minima[residue] = prefix
        return best

