from collections import deque

class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1
        counts = deque(counts)
        for _ in range(t):
            counts.rotate(1)
            counts[1] = (counts[1] + counts[0]) % mod
        return sum(counts) % mod

