import heapq
from math import isqrt

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        size = 10 ** len(str(n))
        low = size // 10
        prime = bytearray(b'\x01') * size
        prime[0:2] = b'\x00\x00'
        for p in range(2, isqrt(size - 1) + 1):
            if prime[p]:
                start = p * p
                prime[start:size:p] = b'\x00' * ((size - 1 - start) // p + 1)
        if prime[n] or prime[m]:
            return -1

        distances = [float('inf')] * size
        distances[n] = n
        heap = [(n, n)]
        places = []
        p = 1
        while p < size:
            places.append(p)
            p *= 10

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != distances[x]:
                continue
            if x == m:
                return cost
            for p in places:
                digit = x // p % 10
                if digit < 9:
                    y = x + p
                    nc = cost + y
                    if not prime[y] and nc < distances[y]:
                        distances[y] = nc
                        heapq.heappush(heap, (nc, y))
                if digit > 0:
                    y = x - p
                    if y >= low and not prime[y]:
                        nc = cost + y
                        if nc < distances[y]:
                            distances[y] = nc
                            heapq.heappush(heap, (nc, y))
        return -1

