class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        l = r = 0
        for k in range(1, n):
            v = min(r - k + 1, z[k - l]) if k <= r else 0
            while k + v < n and nums[v] == nums[k + v]:
                v += 1
            z[k] = v
            if k + v - 1 > r:
                l, r = k, k + v - 1

        ans = 0
        dp = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            bound = (n + i) // 2
            if z[i] >= i:
                ans += max(0, n - 2 * i)
                bound = min(bound, 2 * i - 1)
            x = nums[i]
            for j in range(i + 1, n):
                if x == nums[j]:
                    v = dp[j + 1] + 1
                    dp[j] = v
                    if j <= bound and v >= j - i:
                        ans += 1
                else:
                    dp[j] = 0
        return ans

