class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # A reachability tree toward 0 uses only one outgoing edge per node,
        # so every allowed threshold is sufficient.
        reverse = [[] for _ in range(n)]
        for a, b, w in edges:
            reverse[b].append((a, w))

        dist = [1000001] * n
        dist[0] = 0
        heap = [(0, 0)]
        reached = 0

        while heap:
            cost, u = heappop(heap)
            if cost != dist[u]:
                continue
            reached += 1
            if reached == n:
                return cost
            for v, weight in reverse[u]:
                candidate = max(cost, weight)
                if candidate < dist[v]:
                    dist[v] = candidate
                    heappush(heap, (candidate, v))

        return -1

