from typing import List

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        # Each copy is original shifted by one constant integer.
        low = bounds[0][0] - original[0]
        high = bounds[0][1] - original[0]
        for x, (u, v) in zip(original, bounds):
            low = max(low, u - x)
            high = min(high, v - x)
            if low > high:
                return 0
        return high - low + 1

